body.nl .cmo{display:block;font-family:var(--body);font-size:12px;color:var(--gold2);margin-top:4px;font-weight:400}
body.nl .ihero{position:relative;margin:-24px -24px 0;height:300px;overflow:hidden;background:#1A1512}
body.nl .ihero img{width:100%;height:100%;object-fit:cover;object-position:50% 30%;display:block}
