body.nl .ihx{position:absolute;left:24px;right:24px;bottom:18px;z-index:1}
body.nl .ihx .ik{font-size:11px;letter-spacing:.3em;text-transform:uppercase;color:var(--gold2)}
body.nl .ihx .ih{font-family:var(--display);font-weight:300;font-size:36px;line-height:1.05;margin-top:8px;color:#fff}
body.nl .ilede{font-size:14.5px;line-height:1.65;color:#CFC4B5;font-weight:300;margin:18px 0 14px}
body.nl .ichips{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 18px}
body.nl .ichips span{font-size:11.5px;letter-spacing:.04em;padding:7px 11px;border:1px solid rgba(201,162,75,.35);border-radius:999px;color:#E9E1D5;background:rgba(201,162,75,.06)}
body.nl .iquote{margin:0 0 26px;padding:16px 18px;border-left:2px solid #C9A24B;background:#1A1512;font-family:var(--display);font-style:italic;font-size:18px;line-height:1.5;color:#E9E1D5}
body.nl .iquote cite{display:block;margin-top:8px;font-family:var(--body);font-style:normal;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)}

